preset.frame_eqs_eel:
// buffering bass, mid and treb

db = 0.6*db+.25*bass_att;
dm = 0.6*dm+.25*mid_att;
dt = 0.6*dt+.25*treb_att;

//buffering them again
dbmt = 0.5*dbmt+.33*(db+dm+dt);

//integrations over time
vv = vv + .1 * dbmt;
bb = bb +.1*db;
mm = mm +.1*dm;
tt = tt +.1*tt;

q1 = 0.5*vv;

//so I heard these things were slow as hell in the shaders...
q2 = sin(q1);
q3 = cos(q1);

q4 = tt-bb+.15*vv;
q5 = bb-tt+.15*vv;

//mhhm, color cycling...

q6 = .5+.5*sin(0.15*q1);
q7 = .5+.5*cos(0.21*q1);
q8 = .5+.3*sin(0.05*q1)+.2*cos(0.3*q1);
q9 = .3+.7*sin(0.27*q1);

preset.pixel_eqs_eel:
vx = 0.25+cos(q4*0.2)*1;
vy = 0.25+sin(q5*0.2)*1;
z = 0;
x = x - vx;
y = y - vy;

d = q1*0.1;
xx = sin(d)*x + cos(d)*y;
yy = cos(d)*x - sin(d)*y;

x = xx;
y = yy;

cx = .2+.4*sin(0.2*q3);
cy = .5+.1*tan(q2);
cz = 0.5+.2*sin(0.1*q1);

zoom = 0.32;
w = 1/zoom*(1+sqrt(sqr(z-cz) + sqr(x-cx)+sqr(y-cy)));
dx = -x*w;// + w*y;
dy = -y*w ;// - w*x;

